import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.ecJ-2P1q.js";const c=JSON.parse('{"title":"New Server, Start to Finish","description":"","frontmatter":{},"headers":[],"relativePath":"operations/vps-walkthrough.md","filePath":"operations/vps-walkthrough.md"}'),o={name:"operations/vps-walkthrough.md"};function n(r,e,h,l,p,d){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="new-server-start-to-finish" tabindex="-1">New Server, Start to Finish <a class="header-anchor" href="#new-server-start-to-finish" aria-label="Permalink to &quot;New Server, Start to Finish&quot;">​</a></h1><p>This page takes you from a workflow that runs on your desktop to the same workflow running on a fresh Linux server, with HTTPS if it starts on a Webhook. It follows the <strong>Export for Server → Docker</strong> package. <a href="./server-deploy">Server Deployment</a> is the reference for everything this page touches; follow its links when you want the reasons or the other shapes (bare metal, <code>api</code> mode).</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>A workflow you have already run on the desktop, with every credential it needs saved there.</li><li>A server you can SSH into: x86-64, Ubuntu or Debian. The official image is published for x86-64 only; on ARM, use the source-build files in the package (see <a href="#troubleshooting">Troubleshooting</a>).</li><li>If the workflow starts on a <strong>Webhook</strong>: a domain name you can add a DNS record to, and a secret set in the Webhook node. Without a secret, anyone who finds the URL can run the workflow.</li></ul><p>A workflow that starts on a Schedule or by hand needs no domain and no open web ports. Skip step 3 for it, and in step 5 allow only SSH.</p><h2 id="_1-export-the-package" tabindex="-1">1. Export the package <a class="header-anchor" href="#_1-export-the-package" aria-label="Permalink to &quot;1. Export the package&quot;">​</a></h2><ol><li>Open the workflow and choose <strong>Export → Export for Server</strong>.</li><li>Check the <strong>Trigger</strong> line and the <strong>Credentials</strong> list. Each row names the environment variable the server will read.</li><li>Pick the <strong>Docker</strong> tab, leave the <strong>Status page port</strong> at <code>7700</code> unless it clashes with something on the server, and click <strong>Generate Docker Package</strong>.</li><li>Save the zip. It holds the hash of the workflow&#39;s run secret, so treat it like a credentials file: do not commit it or send it over an unencrypted channel.</li></ol><h2 id="_2-create-the-server-and-upload-the-package" tabindex="-1">2. Create the server and upload the package <a class="header-anchor" href="#_2-create-the-server-and-upload-the-package" aria-label="Permalink to &quot;2. Create the server and upload the package&quot;">​</a></h2><p>Create the server with any provider and sign in over SSH. Then, from your own computer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aerini-package.zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> you@your-server:~</span></span></code></pre></div><p>Use the zip&#39;s real file name. On the server, install <code>unzip</code> if it is missing, then unpack:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unzip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unzip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aerini-package.zip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aerini</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aerini</span></span></code></pre></div><h2 id="_3-point-a-domain-at-the-server-webhook-only" tabindex="-1">3. Point a domain at the server (Webhook only) <a class="header-anchor" href="#_3-point-a-domain-at-the-server-webhook-only" aria-label="Permalink to &quot;3. Point a domain at the server (Webhook only)&quot;">​</a></h2><p>Add an <code>A</code> record (or <code>AAAA</code> for IPv6) for the name you want, such as <code>hooks.example.com</code>, pointing at the server&#39;s public address. Caddy asks for the HTTPS certificate when it starts, so the record has to resolve first.</p><h2 id="_4-install-docker" tabindex="-1">4. Install Docker <a class="header-anchor" href="#_4-install-docker" aria-label="Permalink to &quot;4. Install Docker&quot;">​</a></h2><p>Follow Docker&#39;s own instructions for your distribution: <a href="https://docs.docker.com/engine/install/ubuntu/" target="_blank" rel="noreferrer">Install Docker Engine on Ubuntu</a>, or the matching page for Debian. Use Docker&#39;s repository, not a distribution package, so that you get the Compose plugin. The package needs Docker Engine 20.10 or later with Compose V2. Check:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span></code></pre></div><p>On Debian and Ubuntu the Docker service starts at boot by default; see <a href="./server-deploy#docker-recommended">Server Deployment §Docker</a> for other systems.</p><h2 id="_5-open-the-firewall-webhook-only" tabindex="-1">5. Open the firewall (Webhook only) <a class="header-anchor" href="#_5-open-the-firewall-webhook-only" aria-label="Permalink to &quot;5. Open the firewall (Webhook only)&quot;">​</a></h2><p>Close everything except SSH, HTTP and HTTPS. Allow SSH first, or you lock yourself out:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 80/tcp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 443/tcp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 443/udp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span></span></code></pre></div><p>Also open ports 80 and 443 in your provider&#39;s own firewall or security group if it has one. Caddy needs them to get and renew the certificate. Docker publishes the ports in the package&#39;s Compose file through its own rules, ahead of ufw&#39;s, so what the Compose file publishes is what is reachable. The package binds the status page to <code>127.0.0.1</code> for that reason; do not change that mapping.</p><h2 id="_6-fill-in-credentials-and-start" tabindex="-1">6. Fill in credentials and start <a class="header-anchor" href="#_6-fill-in-credentials-and-start" aria-label="Permalink to &quot;6. Fill in credentials and start&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>In <code>.env</code>, give each credential variable its value. For a Webhook workflow, also set <code>AERINI_DOMAIN</code> to the name from step 3. The <code>docker-compose.yml</code> refuses to start without it. <code>.env</code> holds secrets; keep it on the server only.</p><p>The first start pulls the official image, pinned to the release that exported the package.</p><h2 id="_7-check-that-it-works" tabindex="-1">7. Check that it works <a class="header-anchor" href="#_7-check-that-it-works" aria-label="Permalink to &quot;7. Check that it works&quot;">​</a></h2><p>On the server:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:7700/api/health</span></span></code></pre></div><p>Use your own status port if you changed it. The health route needs no token. To open the status page from your own computer, tunnel to it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 7700:127.0.0.1:7700</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> you@your-server</span></span></code></pre></div><p>Then browse to <code>http://localhost:7700</code>.</p><p>For a Webhook workflow, call it from anywhere (use the package&#39;s own <code>README.md</code> for your exact path and method):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://hooks.example.com/webhook</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;x-webhook-secret: &lt;your-webhook-secret&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;content-type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;hello&quot;: &quot;world&quot;}&#39;</span></span></code></pre></div><p>Only the webhook&#39;s path and method are served; everything else answers 404, and the status page is not reachable through Caddy.</p><h2 id="keeping-it-running" tabindex="-1">Keeping it running <a class="header-anchor" href="#keeping-it-running" aria-label="Permalink to &quot;Keeping it running&quot;">​</a></h2><ul><li><strong>Change the workflow:</strong> edit it on the desktop, export again, replace <code>aerini-server.json</code> on the server with the one from the new zip, then run <code>docker compose restart</code>.</li><li><strong>Update Aerini itself:</strong> export again from a newer app. See <a href="./updating">Updating</a>.</li><li><strong>Back up:</strong> see <a href="./server-deploy#backup-and-restore">Backup and restore</a>. Keep the backup off the server.</li><li><strong>Logs:</strong> <code>docker compose logs -f</code>.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>Likely cause</th></tr></thead><tbody><tr><td><code>Set AERINI_DOMAIN in .env</code></td><td>A Webhook export needs <code>AERINI_DOMAIN</code> set before <code>docker compose up -d</code>.</td></tr><tr><td>Caddy cannot get a certificate</td><td>The DNS record has not reached the server yet, or port 80 or 443 is closed in the provider&#39;s firewall.</td></tr><tr><td>Docker reports the image was not found, or the server is ARM</td><td>The image is published for x86-64 and for released versions only. Build from source: <code>docker compose -f docker-compose.yml -f docker-compose.build.yml up --build -d</code>.</td></tr><tr><td>A node fails although the workflow runs</td><td>Shell, Code and Database nodes are off by default. The package&#39;s README lists the flags to enable them, after you have audited the workflow.</td></tr><tr><td>A credential field is empty in a node</td><td>The variable in <code>.env</code> is missing or misnamed. The names in <code>.env.example</code> are the ones the server reads.</td></tr></tbody></table><p>For anything else, see <a href="./server-deploy">Server Deployment</a> and <a href="./../troubleshooting">Troubleshooting</a>.</p>`,40)])])}const g=s(o,[["render",n]]);export{c as __pageData,g as default};
